	static ByteBuffer pcm16(float[][] channels) {
		if (channels.length == 0) throw new IllegalArgumentException("No audio channels");
		int frames = channels[0].length;
		for (float[] channel : channels) {
			if (channel.length != frames) throw new IllegalArgumentException("Unequal channel lengths");
		}
		ByteBuffer pcm = ByteBuffer.allocate(Math.multiplyExact(Math.multiplyExact(frames, channels.length), 2))
				.order(ByteOrder.LITTLE_ENDIAN);
		for (int frame = 0; frame < frames; frame++) {
			for (float[] channel : channels) {
				int sample = (int) (channel[frame] * 32768.0f);
				pcm.putShort((short) Math.max(-32768, Math.min(32767, sample)));
			}
